import java.beans.*; import java.util.*; class Solution { static class Model { private final PropertyChangeSupport changes=new PropertyChangeSupport(this); private int quantity; int total(int price){return Math.multiplyExact(quantity,price);} void setQuantity(int value){if(value<0)throw new IllegalArgumentException("quantity");int old=quantity;quantity=value;changes.firePropertyChange("quantity",old,value);} void addListener(PropertyChangeListener listener){changes.addPropertyChangeListener(listener);} } static List<String> rows(Map<String,Integer> data){return data.entrySet().stream().sorted(Map.Entry.comparingByKey()).map(entry -> entry.getKey()+":"+entry.getValue()).toList();} }
